/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
p=Path('Task.v')
s=p.read_text().replace('''  induction a; simpl; intros k u Hu;
    try solve [repeat (rewrite ?IHa, ?IHa1, ?IHa2, ?IHa3;
      auto using task_scoped_mono with arith)].''','''  induction a; simpl; intros k u Hu;
    assert (Hsu : task_scoped (S k) u) by
      (eapply task_scoped_mono; [lia | exact Hu]);
    try solve [rewrite ?IHa, ?IHa1, ?IHa2, ?IHa3 by assumption; reflexivity].''')
p.write_text(s)
PY
rocq compile -R . Qual -R .rocq-deps/Metalib Metalib Task.v"

